package org.icu.sepsis.sepsis;
import static org.junit.jupiter.api.Assertions.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class K1WindowComparisonTest {
 final Instant t=Instant.parse("2026-11-06T00:00:00Z");
 K1WindowComparison.CaseInput c(){var c=new K1WindowComparison.CaseInput();c.caseKey="synthetic-case";c.t0=t;c.hospitalAdmission=t.minusSeconds(48*3600);c.sourceComplete=true;return c;}
 K1WindowComparison.Lactate p(double value,int hour,int available){var p=new K1WindowComparison.Lactate();p.value=value;p.time=t.plusSeconds(hour*3600);p.availableAt=t.plusSeconds(available*3600);p.source="synthetic";p.recordId="record-"+hour+"-"+value;p.timeMeaning="采样时间";p.unit="mmol/L";p.valid=true;p.availabilityConfirmed=true;return p;}
 @Test void wideAddsCandidatesAndKeepsExactProvenance(){var c=c();c.lactates=List.of(p(3,-12,-11),p(1,0,0));var wide=K1WindowComparison.evaluate(c,24,6,6);assertEquals(true,wide.get("value"));assertEquals(false,K1WindowComparison.evaluate(c,2,1,6).get("value"));var selected=(Map<?,?>)wide.get("selected");assertEquals(3.0,selected.get("value"));assertEquals(t.minusSeconds(12*3600),selected.get("time"));assertEquals(false,wide.get("qualityUse"));var report=K1WindowComparison.compare(List.of(c),List.of(6));var at=(Map<?,?>)((List<?>)report.get("assessments")).get(0);assertEquals(1,((List<?>)at.get("added")).size());assertTrue(((List<?>)at.get("reduced")).isEmpty());}
 @Test void noFutureInformationAndNoEarlyFinalNegative(){var c=c();c.lactates=List.of(p(1,0,0),p(4,0,4));assertNull(K1WindowComparison.evaluate(c,24,6,1).get("value"));assertEquals(false,K1WindowComparison.evaluate(c,2,1,1).get("value"));assertEquals(true,K1WindowComparison.evaluate(c,24,6,6).get("value"));assertEquals(true,K1WindowComparison.evaluate(c,2,1,6).get("value"));}
 @Test void admissionClipsWindowAndThresholdAndEndpointsAreInclusive(){var c=c();c.hospitalAdmission=t.minusSeconds(3600);c.lactates=List.of(p(99,-2,-2),p(2,-1,-1));assertEquals(2.0,((Map<?,?>)K1WindowComparison.evaluate(c,24,6,6).get("selected")).get("value"));c.lactates=List.of(p(2,6,6));assertEquals(true,K1WindowComparison.evaluate(c,24,6,6).get("value"));}
 @Test void failuresMissingAndUnknownAvailabilityStayUnknown(){var c=c();assertNull(K1WindowComparison.evaluate(c,24,6,6).get("value"));var p=p(3,0,0);c.lactates=List.of(p);c.sourceError=true;assertNull(K1WindowComparison.evaluate(c,24,6,6).get("value"));c.sourceError=false;p.availabilityConfirmed=false;assertNull(K1WindowComparison.evaluate(c,24,6,6).get("value"));p.availabilityConfirmed=true;p.unit="mg/dL";assertNull(K1WindowComparison.evaluate(c,24,6,6).get("value"));}
 @Test void positiveMayBeProvisionalButLowValueNeedsClosedWindow(){var c=c();c.lactates=List.of(p(1,0,0));assertNull(K1WindowComparison.evaluate(c,24,6,3).get("value"));assertEquals(false,K1WindowComparison.evaluate(c,24,6,6).get("value"));c.lactates=List.of(p(2,0,0));assertEquals(true,K1WindowComparison.evaluate(c,24,6,1).get("value"));c.sourceComplete=null;assertNull(K1WindowComparison.evaluate(c,24,6,6).get("value"));}
 @Test void unknownChangesNotCountedAsAddedAndDuplicateCasesRejected(){var c=c();c.lactates=List.of(p(3,-12,-12));var report=K1WindowComparison.compare(List.of(c),List.of(6));var row=(Map<?,?>)((List<?>)report.get("assessments")).get(0);assertTrue(((List<?>)row.get("added")).isEmpty());assertEquals(1,((List<?>)row.get("uncertainChanges")).size());assertThrows(IllegalArgumentException.class,()->K1WindowComparison.compare(List.of(c,c),List.of(6)));}
}
